export { redactor } from "./private.mjs";

export class RunnerProjectionError extends Error {
  constructor(code = "protection_inputs_unavailable") {
    super(`Runner public content withheld: ${code}`);
    this.code = code;
  }
}
export const redactionRecord = (redact) => ({
  schema: "loki.runner.safe-projection/1",
  revision: redact.revision,
});
const prose = (value, redact) =>
  typeof value === "string" ? redact.text(value) : value;
const questions = (items, redact) =>
  items.map((q) => {
    // Model-authored identifiers must remain exact for answering. Do not publish
    // an unsafe identifier or silently rename it into another question.
    if (redact.hasSecret(q.id))
      throw new RunnerProjectionError("unsafe_model_identity");
    return {
      ...q,
      question: prose(q.question, redact),
      kind: prose(q.kind, redact),
    };
  });
export function projectClarification(request, redact) {
  return {
    ...request,
    reason: prose(request.reason, redact),
    completedSteps: request.completedSteps.map((s) => prose(s, redact)),
    remainingSteps: request.remainingSteps.map((s) => prose(s, redact)),
    questions: questions(request.questions, redact),
    redaction: redactionRecord(redact),
  };
}
export function projectTerminal(terminal, redact) {
  const result = { ...terminal };
  for (const field of ["reason", "answer", "message"])
    if (Object.hasOwn(result, field))
      result[field] = prose(result[field], redact);
  if (Array.isArray(result.checks))
    result.checks = result.checks.map((check) => ({
      ...check,
      ...(typeof check.message === "string"
        ? { message: redact.text(check.message) }
        : {}),
    }));
  return result;
}
export function projectRunnerResult(result, redact, stamp = true) {
  const executionReport = result.executionReport
    ? projectClarification(result.executionReport, redact)
    : result.executionReport;
  if (executionReport) delete executionReport.redaction;
  const projected = {
    ...result,
    ...(Object.hasOwn(result, "task")
      ? { task: prose(result.task, redact) }
      : {}),
    terminal: projectTerminal(result.terminal, redact),
    ...(Object.hasOwn(result, "executionReport") ? { executionReport } : {}),
    ...(result.recovery
      ? {
          recovery: {
            ...result.recovery,
            transitions: result.recovery.transitions.map((t) => ({
              ...t,
              reason: prose(t.reason, redact),
            })),
          },
        }
      : {}),
    ...(result.trace
      ? {
          trace: {
            ...result.trace,
            ...(Object.hasOwn(result.trace, "error")
              ? { error: prose(result.trace.error, redact) }
              : {}),
          },
        }
      : {}),
  };
  if (stamp || JSON.stringify(projected) !== JSON.stringify(result))
    projected.redaction = redactionRecord(redact);
  return projected;
}
export function projectRunnerProgress(event, redact, issued = {}) {
  for (const field of ["functions", "actions"])
    if (
      event[field]?.some(
        (value) => !issued[field]?.includes(value) && redact.hasSecret(value),
      )
    )
      return {
        error: {
          schema: "loki.runner.safe-projection-error/1",
          code: "unsafe_model_identity",
        },
        redaction: redactionRecord(redact),
      };
  if (event.result)
    return { ...event, result: projectRunnerResult(event.result, redact) };
  return event.terminal
    ? { ...event, terminal: projectTerminal(event.terminal, redact) }
    : event;
}
export function projectRunnerUi(observation, redact) {
  return {
    ...observation,
    ...Object.fromEntries(
      ["url", "text", "snapshot"]
        .filter((key) => Object.hasOwn(observation, key))
        .map((key) => [key, prose(observation[key], redact)]),
    ),
  };
}
